import {esc,stamp} from './charts.js';
import {candleHTML,bindCandles} from './candles.js';
const price=(p,c='USD')=>Number.isFinite(p)?new Intl.NumberFormat('en-CA',{style:'currency',currency:c}).format(p):'—';
let state={tab:'Stocks & ETFs',query:'',exchange:'CME',currency:'USD',interval:'5m',pending:null,error:'',results:[],instrument:null,bars:[],chains:[],quote:null,chainIndex:0,expiry:'',strike:'',count:100,offset:0,watch:[]},timer;
try{state.watch=JSON.parse(localStorage.getItem('northstar-watchlist')||'[]').filter(c=>Number.isSafeInteger(c.conId)).slice(0,30)}catch{}
const tabs=['Stocks & ETFs','Options','Futures','Crypto'];
export function explorerView(feed,crypto){
 const incoming=feed?.explorer;
 if(incoming?.requestId&&state.pending?.id===incoming.requestId){
  state.error=incoming.status==='error'?incoming.message:'';
  if(incoming.action==='search')state.results=incoming.results||[];
  if(incoming.instrument)state.instrument=incoming.instrument;
  if(incoming.action==='chain'){state.chains=incoming.chains||[];if(!state.expiry)state.expiry=state.chains[0]?.expiries[0]||'';}
  else if(['chart','option'].includes(incoming.action)){state.bars=incoming.bars||[];state.quote=incoming.quote||null;}
  if(['ready','error'].includes(incoming.status))state.pending=null;
 }
 // Quote updates continue after the historical request completes.
 if(incoming?.instrument?.conId===state.instrument?.conId&&incoming?.quote)state.quote=incoming.quote;
 const waiting=state.pending,expired=waiting&&Date.now()-waiting.time>90000;
 const cryptoMode=state.tab==='Crypto',coin=crypto?.assets?.find(c=>c.id===state.instrument?.symbol)||crypto?.assets?.[0];
 const instrument=cryptoMode?{symbol:coin?.id||'BTC/CAD',name:'Kraken spot',currency:'CAD'}:state.instrument;
 const bars=cryptoMode?(coin?.bars||[]):state.bars,q=cryptoMode?{bid:coin?.bid,ask:coin?.ask,mode:'60s snapshots',last:coin?.mid}:state.quote;
 const last=Number.isFinite(q?.last)?q.last:bars.at(-1)?.close;
 const chain=state.chains[state.chainIndex]||state.chains[0];
 const age=Date.now()-Math.min(q?.bidReceivedAt??0,q?.askReceivedAt??0);
 const mode=cryptoMode?'Hourly candles':!feed?.connected?'Disconnected':q?.status==='stale'||age>120000?'Quotes unavailable / stale':q?.mode||'Historical data';
 return `<div class="explore-tabs">${tabs.map(t=>`<button class="${t===state.tab?'active':''}" data-explore-tab="${t}">${t}</button>`).join('')}</div><form id="market-search" class="market-search"><span class="search-glyph">⌕</span><input id="market-query" aria-label="Search markets" value="${esc(state.query)}" placeholder="${state.tab==='Futures'?'Futures root, e.g. ES, MES, CL, GC':'Search any stock or ETF by symbol or company'}" maxlength="40" ${cryptoMode?'disabled':''}>${state.tab==='Futures'?`<select id="market-exchange" aria-label="Futures exchange">${['CME','CBOT','NYMEX','COMEX','CDE'].map(e=>`<option ${state.exchange===e?'selected':''}>${e}</option>`).join('')}</select>`:''}<button class="button" ${cryptoMode?'disabled':''}>Search</button></form><div class="explore-feedback" role="status">${state.error?esc(state.error):expired?'Gateway has not answered yet. Check the Mac connection, then search again.':waiting?'Requesting IBKR data… '+(feed?.transport==='hosted'?'Allow up to 60 seconds for the private relay.':''):state.tab==='Options'?'Search an underlying, then choose expiry, strike and call or put.':state.tab==='Futures'?'Search returns actual listed expiries from your selected exchange.':'Canadian and U.S. listings · Search-powered discovery, not a complete exchange-wide price feed.'}</div><div class="explorer-layout"><aside class="explorer-list panel"><div class="panel-head"><h2>${state.results.length?'Search results':'Watchlist'}</h2><span class="dim">${state.results.length||state.watch.length}</span></div>${cryptoMode?['BTC/CAD','ETH/CAD'].map(id=>`<button class="explore-row" data-coin="${id}"><b>${id}</b><small>Kraken · CAD</small></button>`).join(''):(state.results.length?state.results:state.watch).map((c,i)=>`<button class="explore-row ${c.conId===instrument?.conId?'active':''}" data-result="${i}" data-list="${state.results.length?'results':'watch'}"><b>${esc(c.symbol)}${c.expiry?' · '+esc(c.expiry):''}</b><small>${esc(c.name||c.symbol)}</small><span>${esc(c.currency)} · ${esc(c.primaryExchange||c.exchange)}</span></button>`).join('')||'<div class="empty"><h3>Find your market</h3><p>Search a company, ticker or futures root. Pin instruments here as you explore.</p></div>'}${state.results.length?'<button class="text-button" id="show-watchlist">View saved watchlist</button>':''}</aside><section class="panel explorer-chart"><div class="panel-head"><div><span class="eyebrow">${esc(instrument?.name||'MARKET EXPLORER')}</span><h2>${esc(instrument?.symbol||'Choose an instrument')}${instrument?.expiry?' · '+esc(instrument.expiry):''}${instrument?.right?' · '+esc(instrument.strike)+' '+esc(instrument.right):''}</h2><div class="price-heading">${price(last,instrument?.currency)} <small>${esc(instrument?.currency||'')}</small></div></div><div class="chart-meta"><span class="badge">${esc(mode)}</span>${instrument?.conId?'<button id="pin-instrument" class="button">☆ Watchlist</button>':''}</div></div>${state.tab==='Options'&&chain?`<form id="option-contract" class="option-picker"><label>Chain<select id="option-chain">${state.chains.map((c,i)=>`<option value="${i}" ${i===state.chainIndex?'selected':''}>${esc(c.tradingClass)} · ${esc(c.exchange)} ×${esc(c.multiplier)}</option>`).join('')}</select></label><label>Expiry<select id="option-expiry">${chain.expiries.map(e=>`<option ${e===state.expiry?'selected':''}>${e}</option>`).join('')}</select></label><label>Strike<input id="option-strike" type="number" min="0.01" step="any" required list="option-strikes" value="${esc(state.strike)}" placeholder="Choose strike"><datalist id="option-strikes">${chain.strikes.map(v=>`<option value="${v}">`).join('')}</datalist></label><label>Type<select id="option-right"><option value="C">Call</option><option value="P">Put</option></select></label><button class="button">View contract</button></form>`:''}<div class="chart-toolbar"><div class="segmented">${['1m','5m','1h','1d'].map(t=>`<button data-interval="${t}" class="${t===(cryptoMode?'1h':state.interval)?'selected':''}" ${cryptoMode||!instrument?.conId?'disabled':''}>${t}</button>`).join('')}</div><div class="candle-tools"><button data-pan="older" aria-label="Earlier candles">←</button><button data-zoom="in" aria-label="Zoom in">＋</button><button data-zoom="out" aria-label="Zoom out">−</button><button data-pan="newer" aria-label="Later candles">→</button></div></div>${candleHTML(bars,{symbol:instrument?.symbol,currency:instrument?.currency,count:state.count,offset:state.offset})}<div class="quote-grid"><article class="stat"><span class="label">Bid</span><strong>${price(q?.bid,instrument?.currency)}</strong></article><article class="stat"><span class="label">Ask</span><strong>${price(q?.ask,instrument?.currency)}</strong></article><article class="stat"><span class="label">Last candle</span><strong class="quote-time">${stamp(bars.at(-1)?.time)}</strong></article></div><div class="panel-foot">${cryptoMode?'Kraken completed hourly trades':`IBKR historical trades · ${esc(state.interval)} · ${bars.length} bars returned · Refresh chart to update`} ${instrument?.multiplier?'· Contract multiplier '+esc(instrument.multiplier):''}</div>${!cryptoMode&&instrument?.conId?'<button id="refresh-chart" class="text-button">↻ Refresh chart</button>':''}</section></div>`;
}
async function request(command,render){
 const id=crypto.randomUUID();state.pending={id,time:Date.now()};state.error='';render();
 try{const r=await fetch('/api/explore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...command,id}),signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');}catch(e){state.pending=null;state.error=e.message;render();}
}
function chart(c,render){state.instrument=c;state.bars=[];state.quote=null;state.offset=0;return request({action:'chart',conId:c.conId,exchange:c.exchange,currency:c.currency,interval:state.interval},render)}
export function bindExplorer(root,feed,cryptoData,render){
 const active=()=>state.tab==='Crypto'?(cryptoData?.assets?.find(a=>a.id===state.instrument?.symbol)||cryptoData?.assets?.[0])?.bars||[]:state.bars;
 bindCandles(root,active(),{count:state.count,offset:state.offset,currency:state.tab==='Crypto'?'CAD':state.instrument?.currency});
 root.querySelectorAll('[data-explore-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.exploreTab;state.results=[];state.chains=[];state.pending=null;state.instrument=null;state.bars=[];state.quote=null;state.error='';render()});
 const form=root.querySelector('#market-search');if(form)form.onsubmit=e=>{e.preventDefault();state.query=root.querySelector('#market-query').value.trim();state.exchange=root.querySelector('#market-exchange')?.value||state.exchange;request({action:'search',query:state.query,secType:state.tab==='Futures'?'FUT':'STK',exchange:state.tab==='Futures'?state.exchange:'SMART',currency:state.exchange==='CDE'?'CAD':'USD'},render)};
 root.querySelector('#market-query')?.addEventListener('input',e=>{state.query=e.target.value});
 root.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const c=state[b.dataset.list][Number(b.dataset.result)];state.instrument=c;state.bars=[];state.quote=null;state.chains=[];state.expiry='';state.strike='';state.chainIndex=0;if(state.tab==='Options'&&c.secType==='STK')request({action:'chain',conId:c.conId,exchange:'SMART',currency:c.currency},render);else chart(c,render)});
 root.querySelector('#show-watchlist')?.addEventListener('click',()=>{state.results=[];render()});
 root.querySelector('#pin-instrument')?.addEventListener('click',()=>{const c=state.instrument;state.watch=[c,...state.watch.filter(w=>w.conId!==c.conId)].slice(0,30);try{localStorage.setItem('northstar-watchlist',JSON.stringify(state.watch))}catch{}state.error='Added to your watchlist.';render()});
 root.querySelector('#option-chain')?.addEventListener('change',e=>{state.chainIndex=Number(e.target.value);state.expiry='';render()});
 root.querySelector('#option-expiry')?.addEventListener('change',e=>state.expiry=e.target.value);
 root.querySelector('#option-strike')?.addEventListener('input',e=>state.strike=e.target.value);
 const option=root.querySelector('#option-contract');if(option)option.onsubmit=e=>{e.preventDefault();const c=state.chains[state.chainIndex],u=state.instrument;state.expiry=root.querySelector('#option-expiry').value;state.strike=root.querySelector('#option-strike').value;request({action:'option',symbol:u.symbol,exchange:c.exchange,currency:u.currency,expiry:state.expiry,strike:Number(state.strike),right:root.querySelector('#option-right').value,multiplier:c.multiplier,tradingClass:c.tradingClass,interval:state.interval},render)};
 root.querySelectorAll('[data-interval]').forEach(b=>b.onclick=()=>{state.interval=b.dataset.interval;chart(state.instrument,render)});
 root.querySelector('#refresh-chart')?.addEventListener('click',()=>chart(state.instrument,render));
 root.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{state.count=Math.max(20,Math.min(300,Math.round(state.count*(b.dataset.zoom==='in'?.7:1.4))));render()});
 root.querySelectorAll('[data-pan]').forEach(b=>b.onclick=()=>{state.offset=Math.max(0,Math.min(Math.max(0,active().length-state.count),state.offset+(b.dataset.pan==='older'?30:-30)));render()});
 root.querySelectorAll('[data-coin]').forEach(b=>b.onclick=()=>{state.instrument={symbol:b.dataset.coin};state.offset=0;render()});
 clearTimeout(timer);if(state.pending)timer=setTimeout(()=>{if(!document.activeElement?.closest('form'))render()},90000);
}
